import{z as l,x as B,o as i,c as p,q as s,j as E,D as a,d as o,s as r,S as d,b as t}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"ext2 块组与位图","description":"","frontmatter":{"title":"ext2 块组与位图","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ext2-block-groups.md","filePath":"cs/ext2-block-groups.md","lastUpdated":1791063341000}'),A={name:"cs/ext2-block-groups.md"};function D(c,e,x,m,u,f){const n=B("Mermaid");return i(),p("div",null,[e[2]||(e[2]=s('<h1 id="ext2-块组与位图" tabindex="-1">ext2 块组与位图 <a class="header-anchor" href="#ext2-块组与位图" aria-label="Permalink to &quot;ext2 块组与位图&quot;">​</a></h1><div class="epigraph"><p>把盘切成块组，每组自带 inode 表、块位图与 inode 位图，是为了让元数据离数据更近，而不是再做一张全局 FAT。</p><footer>—— 据 Card, Ts&#39;o, Tweedie, Design and Implementation of the Second Extended Filesystem；McKusick et al., A Fast File System for UNIX</footer></div><p><a href="/cs/fat-filesystem">上一课</a>把文件变成簇链。缺口立刻暴露：一张 FAT 是随机写热点，大卷上扫空闲项也贵。Unix 主干的 <a href="/cs/inode-dir">inode</a> 需要落盘位置。<a href="/cs/ext4-journal">FFS</a> 之前的布局课序在此补 <strong>ext2 块组</strong>：位图代替链表，inode 表按组切开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FAT 的「下一簇」与「空闲」挤在同一数组；inode 若也做成一张巨大线性表，柱面（或闪存擦除带）两端来回跑。McKusick 的 FFS 把盘分成柱面组；ext2 把同一直觉收成块组（block group）。缺口不是再定义 inode，而是：超级块描述组大小，每组有块位图、inode 位图、inode 表，数据块尽量落在 inode 所在组。</p><p>本课不把 ext3 日志再讲一遍，那是 <a href="/cs/ext4-journal">JBD2</a> 已钉过的对象。</p><p><span class="marginnote">位图每一位对应一组内一块或一个 inode。分配先试文件所在组，满了再扩组。间接块仍是 inode 里的树，不是 FAT 链。</span><span class="marginnote">术语翻译：位图就是用一排 0/1 当「占座表」——每一位代表一块（或一个 inode），1 表示已被占用、0 表示空闲。找一个空块，就是在这串位里扫第一个 0，而不是顺着链表一格格跳。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>mkfs 按块大小与 inode 比率切组。<code>creat</code>：在目录所在组找空闲 inode 位，初始化 inode（模式、链接计数、时间），再在目录文件里写名字与 inode 号——这是 Unix 目录项，不是 FAT 的「首簇即身份」。写数据：按 inode 的直接/间接指针填块号，同时把块位置 1。读：inode → 块号 → <a href="/cs/page-cache">页缓存</a> 填页，不再沿 FAT 跳。</p>',9)),(i(),E(d,null,{default:a(()=>[r(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SB%5B%22%E8%B6%85%E7%BA%A7%E5%9D%97%22%5D%20--%3E%20BG%5B%22%E5%9D%97%E7%BB%84%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%0A%20%20BG%20--%3E%20IBM%5B%22inode%20%E4%BD%8D%E5%9B%BE%E4%B8%8E%E8%A1%A8%22%5D%0A%20%20BG%20--%3E%20BBM%5B%22%E5%9D%97%E4%BD%8D%E5%9B%BE%22%5D%0A%20%20IBM%20--%3E%20INO%5B%22inode%20%E6%8C%87%E9%92%88%E6%A0%91%22%5D%0A%20%20INO%20--%3E%20DAT%5B%22%E6%9C%AC%E7%BB%84%E6%95%B0%E6%8D%AE%E5%9D%97%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t("h2",{id:"机制",tabindex:"-1"},[o("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=t("p",null,"块组把分配局部化：同一目录的文件倾向同一组，降低磁头行程（HDD）或让元数据与数据共享闪存局部性。超级块与组描述符常有备份，避免单点损坏整卷。对照 FAT：空闲查询是位图扫描或 buddy 式的内存缓存，不是跟链表。间接指针让大文件随机访问 \\(O(\\log)\\) 次块读，而不是 \\(O(\\text{簇数})\\) 的链走。",-1)),e[5]||(e[5]=t("p",null,"崩溃窗口与主干一致：位图、inode、目录项三者可能互指错误，于是才有后课的日志、软更新与 fsck。本课只把「布局已经是 Unix 形状」钉住。",-1)),(i(),E(d,null,{default:a(()=>[r(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22creat(name)%22%5D%20--%3E%20G%5B%22%E9%80%89%E7%9B%AE%E5%BD%95%E6%89%80%E5%9C%A8%E7%9A%84%E5%9D%97%E7%BB%84%22%5D%0A%20%20G%20--%3E%20FI%5B%22%E7%BF%BB%E8%BD%AC%20inode%20%E4%BD%8D%E5%9B%BE%E4%B8%80%E6%A0%BC%E5%B9%B6%E5%88%9D%E5%A7%8B%E5%8C%96%20inode%22%5D%0A%20%20FI%20--%3E%20DE%5B%22%E5%90%91%E7%9B%AE%E5%BD%95%E6%96%87%E4%BB%B6%E5%86%99%E5%85%A5%EF%BC%9A%E5%90%8D%E5%AD%97%20%2B%20inode%20%E5%8F%B7%22%5D%0A%20%20DE%20--%3E%20DB%5B%22%E5%86%99%E6%95%B0%E6%8D%AE%E5%9D%97%EF%BC%9A%E7%BF%BB%E8%BD%AC%E5%9D%97%E4%BD%8D%E5%9B%BE%E5%AF%B9%E5%BA%94%E6%A0%BC%22%5D%0A%20%20DB%20--%3E%20UP%5B%22%E6%8A%8A%E5%9D%97%E5%8F%B7%E5%A1%AB%E8%BF%9B%20inode%20%E6%8C%87%E9%92%88%E6%A0%91%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=s('<p><span class="marginnote">为什么重要：一次 creat 要动三处盘上结构——inode 位图、目录内容、块位图——任何一处先落盘、其余没落盘，崩溃后就是「inode 已占但目录里没名字」这类孤儿。这个窗口正是后来日志文件系统要关掉的门。</span></p><p>不要把块组写成 RAID 条带：条带是块设备的几何，块组是文件系统自己的切法，可以落在一块盘上。<span class="marginnote">数字实例：位图必须装进一块，这条约束有多紧？块大小 \\(4\\,\\text{KiB}\\) 时，一块位图有 \\(4096\\times 8=32768\\) 位，正好管 \\(32768\\) 块 \\(=128\\,\\text{MiB}\\)——这就是「每组最多 32768 块」的来历。</span></p><p>实现上：块组大小受位图必须装进一块的约束：4KiB 块则每组最多 32768 块。inode 比率在 mkfs 时选定，事后增加 inode 表很痛，这是布局一旦写成盘就难改的例子。 读法上只引用<a href="/cs/fat-filesystem">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 布局与日志」课序里，对象是 <strong>ext2 块组与位图</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 extent、延迟分配、flex_bg。不保证 32 位块号的 ext2 能装下今日的盘——那是 ext4 的地址与 extent 课。下一课把「一级级间接块」换成连续区段描述符。</p><p>版本字段会变，课序钉的是机制对象「ext2 块组与位图」，不是某一主线内核的结构体名。 后课默认：ext2 用块组 + 位图 + inode 指针树。大文件如何少间接块、如何表示空洞，下一课 extent。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ext2 按块组切盘；位图管空闲，inode 表在组内。</li><li>文件用直接/间接指针，不再走 FAT 链。</li><li>extent 是下一课的缺口。</li><li>出处：Card, Ts&#39;o, Tweedie；McKusick et al., FFS；Arpaci-Dusseau, <em>OSTEP</em>。</li></ul>',10))])}const F=l(A,[["render",D]]);export{T as __pageData,F as default};
